/* Pixel-inspired palette: dark navy, bright cyan, soft yellow, white */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #e0e0e0;
  --highlight: #f9c74f;
  --border-radius: 8px;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  border-radius: var(--border-radius);
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--highlight);
  text-shadow: 2px 2px 0 var(--primary);
  letter-spacing: 2px;
}

.form-group {
  margin-bottom: 20px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: bold;
  color: var(--highlight);
}

input, select {
  width: 100%;
  padding: 12px;
  font-family: var(--font);
  font-size: 1.1rem;
  background: var(--bg);
  border: 3px solid var(--primary);
  border-radius: var(--border-radius);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

button {
  width: 100%;
  padding: 14px;
  font-family: var(--font);
  font-size: 1.2rem;
  font-weight: bold;
  background: var(--accent);
  color: white;
  border: 3px solid var(--accent);
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

button:hover {
  background: #c73a4f;
  border-color: #c73a4f;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--primary);
}

button:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

.result-area {
  margin-top: 24px;
  padding: 16px;
  background: var(--bg);
  border: 3px solid var(--primary);
  border-radius: var(--border-radius);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 1.3rem;
}

.result-label {
  font-weight: bold;
  color: var(--highlight);
}

#result {
  font-size: 1.6rem;
  font-weight: bold;
  color: var(--accent);
  min-width: 80px;
  text-align: right;
}

.formulas {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 2px dashed var(--primary);
  font-size: 0.9rem;
  color: #aaa;
}

.formulas p {
  margin: 4px 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  body {
    font-size: 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const tempInput = document.getElementById('temperature');
  const directionSelect = document.getElementById('direction');
  const convertBtn = document.getElementById('convert');
  const resultOutput = document.getElementById('result');

  function convert() {
    const raw = tempInput.value.trim();
    const num = parseFloat(raw);

    if (raw === '' || !isFinite(num)) {
      resultOutput.textContent = 'Error';
      return;
    }

    const direction = directionSelect.value;
    let result;

    if (direction === 'c-to-f') {
      result = num * 9 / 5 + 32;
    } else if (direction === 'f-to-c') {
      result = (num - 32) * 5 / 9;
    } else {
      resultOutput.textContent = 'Error';
      return;
    }

    resultOutput.textContent = result.toFixed(2);
  }

  convertBtn.addEventListener('click', convert);

  // Allow pressing Enter in the input to trigger conversion
  tempInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      convert();
    }
  });
});
